"""Seal existing RAW2K synthetic/observable-functional results;no input replay."""
from pathlib import Path
import datetime,hashlib,json,re
R=Path(__file__).resolve().parent

def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
def new(p,obj):assert not p.exists(),str(p);p.write_text(json.dumps(obj,ensure_ascii=False,indent=2,allow_nan=False)+'\n',encoding='utf-8')
def meta(p):return {'path':str(p),'relative':p.relative_to(R).as_posix(),'bytes':p.stat().st_size,'SHA':sha(p)}
def main():
    assert not (R/'INDEX.json').exists();run=R/'attempts/001';res=json.loads((run/'RESULT.json').read_text(encoding='utf-8'));s=json.loads((run/'shadow/SUMMARY.json').read_text(encoding='utf-8'));assert res['all_passed'] and res['units']['tests']==13 and s['total_frames']==3200 and s['total_samples']==63848 and s['unique_source_samples']==63846 and s['joined_steady_samples']==63840
    for x in res['source_files']:assert sha(R/x['name'])==x['SHA'];assert sha(run/'sources'/x['name'])==x['SHA']
    for p,h in res['protected_hashes'].items():assert sha(Path(p))==h
    outputs=[]
    for e in s['artifacts']:
        p=Path(e['path']);assert p.is_relative_to(run/'shadow') and p.stat().st_size==e['bytes'] and sha(p)==e['producer_SHA'];outputs.append({**meta(p),'producerSHA_verified_new_derived_output':True})
    table=[];totals={k:0 for k in ('50000','100000','150000')}
    for c in s['cases']:
        for k,w in c['windows'].items():
            assert w['continuous_trusted_cue_rows']==0 and w['all_trusted_cues_uncertain'] and w['continuous_true_COM_radius'] is None
            table.append({'id':c['id'],'T_ms':w['T_ms'],'numeric_windows':w['numeric_windows'],'age_p50_ms':w['window_average_age_us']['p50']/1000,'paired_vector_delta_p50_m_s2':w['paired_raw_minus_mean_vector_difference_m_s2']['p50'],'paired_vector_delta_p95_m_s2':w['paired_raw_minus_mean_vector_difference_m_s2']['p95'],'paired_vector_delta_max_m_s2':w['paired_raw_minus_mean_vector_difference_m_s2']['max'],'conditional_discrete_radius_p50_m_s2':w['proposed_discrete_radius_m_s2']['p50'],'conditional_discrete_radius_p95_m_s2':w['proposed_discrete_radius_m_s2']['p95'],'continuous_physical_radius':None,'trusted_cue_rows':0});totals[k]+=w['numeric_windows']
    new(R/'CASE_WINDOW_TABLE.json',{'table':table,'totals_by_T_us':totals,'paired_difference_is_not_trueCOM_error':True,'continuous_radius_unbound_all':True,'overlapping_windows_not_independent_trials':True})
    new(R/'SOURCE_RESULT_INDEX.json',{'executed_source_files':res['source_files'],'raw_sensor_only_inputs':s['input_reads'],'old_dependency_protection_SHA':res['protected_hashes'],'derived_outputs':outputs,'no_neighbor_original_trace_result_DR_GT_read':True})
    new(R/'FRAME_CLOCK_AUDIT.json',{'frames':s['total_frames'],'total_samples':s['total_samples'],'unique_source_samples':s['unique_source_samples'],'steady_joined_samples':s['joined_steady_samples'],'cases':[{'id':x['id'],'frames':x['frames'],'boot_frames_excluded':x['boot_frames_excluded'],'duplicate_source_frames_excluded':x['duplicate_source_frames_excluded'],'mean_raw_reprojection_roundoff_max':x['max_authoritative_mean_vs_raw_recompute_roundoff'],'epoch_qend_vs_last_rawq_difference':x['epoch_endpoint_joint_q_minus_last_rawq_maxabs'],'endpoint_geometry_events':x['endpoint_geometry_events']} for x in s['cases']],'sample_last_epoch_offset_us':500,'raw_endpoints_same_time':True,'mean_packet_endpoint_not_falsely_synchronized':True,'authoritative_mean_equals_old_packet':'producer claim, original packet not read by consumer','no_IID_noise_reduction':True})
    new(R/'VALIDATION.json',{'status':'RAW2K_DISCRETE_COM_FUNCTIONAL_MATH_AND_SIX_SENSOR_SHADOW_PASS_CONTINUOUS_CUE_UNBOUND','units':res['units'],'frame_sample_counts':[3200,63848,63846,63840],'totals_by_window_T_us':totals,'source_and_derived_SHA_verified':True,'protected_SHA_unchanged':res['protected_hashes'],'observable_comparison':'same-time raw endpointu, raw2kpath vs authoritative100Hzmean constantbins at identical windowtimes; NOT trueCOMerror','continuous_truth_or_quadrature_bound':None,'hardware_binding':False,'all_trusted_cues_unknown':True,'confidence_cap':.50,'frozen_threshold':.60,'original_trace_result_DR_GT_reads':0,'newphysics_Git_GPU_agents_realIO':False,'PH4pending':True})
    lines=[]
    for x in table:lines.append(f"|{x['id']}|{int(x['T_ms'])}|{x['numeric_windows']}|{x['age_p50_ms']:.1f}|{x['paired_vector_delta_p95_m_s2']:.6f}|{x['paired_vector_delta_max_m_s2']:.6f}|{x['conditional_discrete_radius_p50_m_s2']:.6f}|0|")
    readme='''# RAW2K COM Window v1 — 可观察离散functional，不冒continuous真值\n\n**13/13新synthetic/SO3/analytic-bin/prefix/时序/allowlist单测首轮通过；6条sensor-onlyprojection全部SHA/bytes/frames核验。3200frames、63848samples，sourceSeq去重63846，另排除6instantboot后63840steady2k points。0新physics/Git/GPU/newagent/真实IO，PH4pending。**\n\n## 先给正确结论\n\n2k path现在确实可见，用真实同时间raw q/qd/gyro/proper端点得到有限窗口离散functional；它与100Hzmean constantbin近似在动态段有可见差别。**差值不是连续trueCOM误差，不是新branch比旧benchmark真实更准的证明。** R38无独立2kworldCOM/contacttruth，sub-.5ms motion/covariance/quadrature仍无保证，continuous radius=None，所有trusted cue UNKNOWN，cap.50/冻结.60门槛不改。\n\n## 每case/窗口\n\npaired delta=两个noisy-sensor离散近似的vector差norm；radius仅对新discrete functional在声明noise/model假设下计算。不是硬件误差/概率。\n\n|case|T ms|数值窗口|平均量age p50 ms|paired delta p95 m/s²|max delta|discrete radius p50|可信cue|\n|---|---:|---:|---:|---:|---:|---:|---:|\n'''+ '\n'.join(lines)+'''\n\n[完整表](<CASE_WINDOW_TABLE.json>)及[六案summary](<attempts/001/shadow/SUMMARY.json>)保留mean/raw mean roundoff、boot/duplicate/clock和区间细节。高度重叠窗口不是独立case，也不是qualify次数。\n\n## 定义：同时间raw边界，不混旧epoch点\n\n在500us pre-step采样点上，q/qd/gyro/proper相同timestamp。估计器用末条raw时间`sourceEpoch−500us`作为window_end，起点恰早50/100/150ms，端点u只用该两个raw sample：\n\n```text\nu = omega×(rCOM(q)−sIMU) + J(q)*qd + nominalWheelPhaseTerm\nR_(i+1)=R_i exp([gyro_i]h)\nI_(i+1)=I_i + R_i [integral_0^h exp([gyro_i]t)dt] fIMU_i\nwindow_specific_force = I_window/T + (Rrel_end*u_end-u_start)/T\n```\n\n每sample constant-bin transport用解析SO3指数积分；prefix只为O(1)取任意窗口，relativewindow-start R=I，不用worldyaw/姿态。没有alpha/qdd差分、没有加g。此定义是**piecewise-held noisy sampled functional**，不是“sampled值等于连续实际trajectory”的断言。\n\n原packet的endpoint_joint_pos4在sourceEpoch，比末raw晚.5ms，不会和旧mean qd/gyro拼成伪同步端点。window average年龄=T/2+arrival−lastRaw，所以nominal25.5/50.5/75.5ms；观测到10msqueue时35.5/60.5/85.5ms。重复sourceSeq不重积分、不赚持续窗，bootinstant单独丢弃；gap不插值凑窗口。\n\n## 旧mean近似如何公平比较\n\n使用原authoritative100Hzmean gyro/proper，在其原窗口support内作constant-bin model；但截取与rawfunctional**完全相同的t0/t1和同一rawu端点**。首/尾mean bin可能仅部分overlap，避免把错时端点误差混入transport比较。它不是旧epoch-endpoint策略的byte-replay，也没读取旧controller输出/原trace。比较的不同来自noisyraw intrawindow信息与mean模型差，不能拿它当连续物理精度。\n\n## 保留的误差与未获得的资格\n\n- 新原始资料同window共用D1offset，是information-enhancement/correlated-noise新branch，不是IID2k；噪声预算不除sqrt20或窗口N，gyro drift/model端点界不凭空相消。\n- 仅因raw端点确有同时间采集，取消旧mean endpoint5.25ms错时项；PUBLICnoise/encoderzero allowance、nominalMCI/J/lever、missingwheelphase界都保留，不把少一个时间误差项当校准。\n- 新窗口radius是**discrete functional**条件budget。未知sub-.5ms变化/gyro-proper关联/真实模型误差的continuous quadrature不能伪造成严格硬件球；因此continuous radius始终unknown，不集成FSM/actuation。\n- authoritative均值与旧packet一致是producer声明；本consumer不读完整packettrace去重验。只核投影内部raw重算mean，roundoff最大约2.13e−14，非bitidentical；不把数值微差/均值同值叫同难度benchmark。\n- 真COM/netforce可能不同：所有model及D0相关误差保持unbound/条件标签，未读DRreceipt逆算取消它们。净力窗口cue也不识别接触身份/全表面air。\n\n## 证据/后续\n\n[scope/functional](<SCOPE_AND_FUNCTIONAL.md>)、[runtime](<raw_functional.py>)、[shadow](<shadow_cases.py>)、[新tests](<test_raw_functional.py>)、[run RESULT/sourceSHA](<attempts/001/RESULT.json>)、[原unit log](<attempts/001/unittest.log>)、[frame时钟审计](<FRAME_CLOCK_AUDIT.json>)、[source/result/derivedproducer索引](<SOURCE_RESULT_INDEX.json>)、[validation](<VALIDATION.json>)、[INDEX](<INDEX.json>)。\n\n[未来动态验证要求](<FUTURE_VALIDATION_REQUIREMENTS.md>)只列独立spin/jump/movingleg/guide支承及私有highrate truthgrade的需求，未新physics/改父publisher。原100Hz controller没使用这些raw作actuation，旧rough/COM/CONTACT和封存source保护SHA均不变。全部新结果PH4pending，整体Goal继续active。\n'''
    (R/'README.md').write_text(readme,encoding='utf-8');files=sorted(p for p in R.rglob('*') if p.is_file() and '__pycache__' not in p.parts and p.name!='INDEX.json');new(R/'INDEX.json',{'name':'RAW2K_COM_WINDOW_V1','status':'SEALED_NEW_CORRELATED_DISCRETEFUNCTIONAL_SHADOW_NO_CONTINUOUS_OR_HARDWARE_QUALIFICATION','core':meta(R/'raw_functional.py'),'shadow':meta(R/'shadow_cases.py'),'README':meta(R/'README.md'),'validation':meta(R/'VALIDATION.json'),'source_result':meta(R/'SOURCE_RESULT_INDEX.json'),'six_manifest_only_inputs':s['input_reads'],'input_manifest_SHA':s['input_manifest_SHA'],'trusted_cues_all_unknown':True,'PH4pending':True,'newphysics_Git_GPU_agents_realIO':False,'original_trace_result_DR_GT_reads':0,'sealed_at_utc':datetime.datetime.now(datetime.timezone.utc).isoformat(),'files':[meta(p) for p in files]})
    for p in R.glob('*.md'):
        for link in re.findall(r'\]\(<([^>]+)>\)',p.read_text(encoding='utf-8')):assert (p.parent/link.split('#')[0]).exists()
    print(json.dumps({'INDEX':meta(R/'INDEX.json'),'README':meta(R/'README.md'),'VALIDATION':meta(R/'VALIDATION.json'),'units':res['units'],'totals':totals,'case_window_table':table,'old_protected_unchanged':True,'newphysics':0},ensure_ascii=False,indent=2))
if __name__=='__main__':main()
